<section class="admin-page-toolbar"><p>Pesan yang dikirim dari formulir Kontak publik.</p></section>
<?php if($messages===[]):?><section class="card-surface empty-state"><h2>Belum ada pesan masuk</h2><p>Pesan pengunjung akan tercatat di sini.</p></section><?php else:?><div class="card-surface table-scroll"><table class="admin-table"><thead><tr><th>Pengirim</th><th>Email</th><th>Pesan</th><th>Tanggal</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($messages as $message):?><tr class="<?=((int)$message['is_read']===0?'message-unread':'')?>"><td><strong><?=e($message['full_name'])?></strong></td><td><a href="mailto:<?=e($message['email'])?>"><?=e($message['email'])?></a></td><td><?=e(mb_strimwidth($message['message'],0,65,'…'))?></td><td><?=e(date('d M Y H:i',strtotime($message['created_at'])))?></td><td><span class="status-pill <?=((int)$message['is_read']===0?'status-open':'status-closed')?>"><?=((int)$message['is_read']===0?'Belum dibaca':'Sudah dibaca')?></span></td><td><a href="<?=url('/admin/pesan/'.$message['id'])?>">Lihat</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
